"""Generated by deploy/build_bundle.py from contracts/resource.py and contracts/proof.py.
Comments removed to keep the deploy small; read them in those files."""
VERIFIED = 'verified'
MISSING = 'missing'
UNREACHABLE = 'unreachable'
WELL_KNOWN = '/.well-known/genlayer-attest.txt'
GIST_HOST = 'api.github.com'
_MAX_DOMAIN = 100
_MAX_HANDLE = 39
_MAX_GIST = 64

def valid_domain(domain: str) -> bool:
    d = (domain or '').strip().lower()
    if not d or len(d) > _MAX_DOMAIN or d.startswith('.') or d.endswith('.') or ('..' in d):
        return False
    if d.startswith('-') or d.endswith('-'):
        return False
    for ch in d:
        if not ('0' <= ch <= '9' or 'a' <= ch <= 'z' or ch in '-.'):
            return False
    return '.' in d

def valid_handle(handle: str) -> bool:
    h = (handle or '').strip()
    if not h or len(h) > _MAX_HANDLE:
        return False
    if h.startswith('-') or h.endswith('-') or '--' in h:
        return False
    for ch in h:
        if not ('0' <= ch <= '9' or 'a' <= ch <= 'z' or 'A' <= ch <= 'Z' or (ch == '-')):
            return False
    return True

def valid_gist_id(gist_id: str) -> bool:
    g = (gist_id or '').strip()
    if not g or len(g) > _MAX_GIST:
        return False
    for ch in g:
        if not ('0' <= ch <= '9' or 'a' <= ch <= 'f' or 'A' <= ch <= 'F'):
            return False
    return True

def token_for(owner_hex: str, kind: str, resource: str) -> str:
    return 'genlayer-attest=' + owner_hex.strip().lower() + ':' + kind + ':' + resource.strip().lower()

def domain_url(domain: str) -> str:
    return 'https://' + domain.strip().lower() + WELL_KNOWN

def gist_url(gist_id: str) -> str:
    return 'https://' + GIST_HOST + '/gists/' + gist_id.strip()

def token_present(body: str, token: str) -> bool:
    if not token:
        return False
    for line in (body or '').replace('\r\n', '\n').replace('\r', '\n').split('\n'):
        if line.strip() == token:
            return True
    return False

def gist_owner(document) -> str:
    if not isinstance(document, dict):
        return ''
    owner = document.get('owner')
    if not isinstance(owner, dict):
        return ''
    login = owner.get('login')
    return login if isinstance(login, str) else ''

def gist_text(document) -> str:
    if not isinstance(document, dict):
        return ''
    files = document.get('files')
    if not isinstance(files, dict):
        return ''
    parts = []
    for name in sorted(files):
        entry = files[name]
        if not isinstance(entry, dict) or entry.get('truncated') is True:
            continue
        content = entry.get('content')
        if isinstance(content, str):
            parts.append(content)
    return '\n'.join(parts)

def same_handle(a: str, b: str) -> bool:
    return (a or '').strip().lower() == (b or '').strip().lower()

def epoch_seconds(stamp: str):
    s = (stamp or '').strip()
    if len(s) < 19 or s[4] != '-' or s[7] != '-' or (s[10] != 'T') or (s[13] != ':') or (s[16] != ':'):
        return None
    for i in (0, 1, 2, 3, 5, 6, 8, 9, 11, 12, 14, 15, 17, 18):
        if not '0' <= s[i] <= '9':
            return None
    year, month, day = (int(s[0:4]), int(s[5:7]), int(s[8:10]))
    hour, minute, second = (int(s[11:13]), int(s[14:16]), int(s[17:19]))
    if not 1 <= month <= 12 or day < 1 or day > _days_in_month(year, month):
        return None
    if hour > 23 or minute > 59 or second > 60:
        return None
    return _days_from_civil(year, month, day) * 86400 + hour * 3600 + minute * 60 + second

def _days_in_month(year: int, month: int) -> int:
    if month == 2:
        leap = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
        return 29 if leap else 28
    return 30 if month in (4, 6, 9, 11) else 31

def _days_from_civil(year: int, month: int, day: int) -> int:
    y = year - (1 if month <= 2 else 0)
    era = (y if y >= 0 else y - 399) // 400
    year_of_era = y - era * 400
    day_of_year = (153 * (month + (-3 if month > 2 else 9)) + 2) // 5 + day - 1
    day_of_era = year_of_era * 365 + year_of_era // 4 - year_of_era // 100 + day_of_year
    return era * 146097 + day_of_era - 719468

def end_of_day(day: str):
    stamp = (day or '').strip()
    if len(stamp) != 10:
        return None
    return epoch_seconds(stamp + 'T23:59:59Z')

def next_day(day: str):
    at = epoch_seconds((day or '').strip() + 'T12:00:00Z')
    if at is None:
        return None
    return _civil_from_days(at // 86400 + 1)

def _civil_from_days(days: int) -> str:
    z = days + 719468
    era = (z if z >= 0 else z - 146096) // 146097
    day_of_era = z - era * 146097
    year_of_era = (day_of_era - day_of_era // 1460 + day_of_era // 36524 - day_of_era // 146096) // 365
    year = year_of_era + era * 400
    day_of_year = day_of_era - (365 * year_of_era + year_of_era // 4 - year_of_era // 100)
    mp = (5 * day_of_year + 2) // 153
    day = day_of_year - (153 * mp + 2) // 5 + 1
    month = mp + (3 if mp < 10 else -9)
    if month <= 2:
        year += 1
    return f'{year:04d}-{month:02d}-{day:02d}'
from dataclasses import dataclass
import genlayer as gl
from genlayer.types import *
KIND_DOMAIN = 'domain'
KIND_HANDLE = 'handle'

@gl.storage.allow
@dataclass
class Claim:
    owner: Address
    kind: str
    resource: str
    locator: str
    token: str
    url: str
    opened_at: str
    status: str
    checked_at: str
    note: str

class Proof(gl.contract.Contract):
    claims: gl.storage.TreeMap[str, Claim]
    claim_ids: gl.storage.DynArray[str]

    def __init__(self):
        pass

    @gl.public.write
    def claim_domain(self, domain: str) -> dict:
        name = domain.strip().lower()
        if not valid_domain(name):
            raise gl.vm.UserError('a domain is a bare hostname, with no scheme, port or path')
        return self._open(KIND_DOMAIN, name, '', domain_url(name))

    @gl.public.write
    def claim_handle(self, handle: str, gist_id: str) -> dict:
        name = handle.strip()
        if not valid_handle(name):
            raise gl.vm.UserError("a handle is GitHub's own username shape")
        gist = gist_id.strip()
        if not valid_gist_id(gist):
            raise gl.vm.UserError('a gist id is hexadecimal')
        return self._open(KIND_HANDLE, name.lower(), gist, gist_url(gist))

    def _open(self, kind: str, resource: str, locator: str, url: str) -> dict:
        owner = gl.message.sender_address
        claim_id = owner.as_hex.lower() + ':' + kind + ':' + resource
        if claim_id in self.claims:
            raise gl.vm.UserError('that claim already exists; check it instead: ' + claim_id)
        token = token_for(owner.as_hex, kind, resource)
        self.claims[claim_id] = Claim(owner=owner, kind=kind, resource=resource, locator=locator, token=token, url=url, opened_at=_stamp(), status='', checked_at='', note='publish the token, then call check')
        self.claim_ids.append(claim_id)
        return _as_dict(claim_id, self.claims[claim_id])

    @gl.public.write
    def check(self, claim_id: str) -> dict:
        key = claim_id.strip().lower()
        if key not in self.claims:
            raise gl.vm.UserError('no such claim: ' + key)
        claim = self.claims[key]
        url = claim.url
        token = claim.token
        kind = claim.kind
        expect = claim.resource

        def leader_fn():
            return _probe(kind, url, token, expect)

        def validator_fn(leaders_res) -> bool:
            if not isinstance(leaders_res, gl.vm.Return):
                return False
            leader = leaders_res.calldata
            if not isinstance(leader, dict) or 'status' not in leader:
                return False
            mine = _probe(kind, url, token, expect)
            if mine['status'] == UNREACHABLE:
                return str(leader['status']) == UNREACHABLE
            if str(leader['status']) == UNREACHABLE:
                return False
            return str(leader['status']) == mine['status'] and str(leader['note']) == mine['note']
        agreed = gl.vm.run_nondet(leader_fn, validator_fn)
        status = str(agreed['status'])
        if status not in (VERIFIED, MISSING, UNREACHABLE):
            raise gl.vm.UserError('unknown check outcome')
        claim.status = status
        claim.checked_at = _stamp()
        claim.note = str(agreed['note'])
        self.claims[key] = claim
        return _as_dict(key, claim)

    @gl.public.view
    def get_claim(self, claim_id: str) -> dict:
        key = claim_id.strip().lower()
        if key not in self.claims:
            raise gl.vm.UserError('no such claim: ' + key)
        return _as_dict(key, self.claims[key])

    @gl.public.view
    def is_verified(self, claim_id: str) -> bool:
        key = claim_id.strip().lower()
        if key not in self.claims:
            return False
        return self.claims[key].status == VERIFIED

    @gl.public.view
    def claim_list(self) -> list:
        return [c for c in self.claim_ids]

    @gl.public.view
    def count(self) -> int:
        return len(self.claim_ids)

    @gl.public.view
    def token_for_claim(self, owner: str, kind: str, resource: str) -> str:
        return token_for(_address(owner).as_hex, kind.strip(), resource.strip().lower())

def _stamp() -> str:
    return str(gl.message.raw['datetime'])

def _address(value) -> Address:
    if hasattr(value, 'as_hex'):
        return value
    return Address(str(value).strip())

def _probe(kind: str, url: str, token: str, expect: str) -> dict:
    import json
    try:
        resp = gl.nondet.web.get(url)
        status = int(resp.status)
        body = (resp.body or b'').decode('utf-8', errors='replace')
    except Exception:
        return {'status': UNREACHABLE, 'note': 'the document could not be fetched'}
    if status == 404:
        return {'status': MISSING, 'note': 'nothing is published at that address'}
    if status < 200 or status >= 300:
        return {'status': UNREACHABLE, 'note': 'the host answered ' + str(status)}
    if kind == KIND_DOMAIN:
        if token_present(body, token):
            return {'status': VERIFIED, 'note': 'the token is published at that domain'}
        return {'status': MISSING, 'note': 'the document does not carry the token'}
    try:
        document = json.loads(body)
    except Exception:
        return {'status': UNREACHABLE, 'note': 'the api did not answer json'}
    login = gist_owner(document)
    if not login:
        return {'status': MISSING, 'note': 'that gist names no owner'}
    if not same_handle(login, expect):
        return {'status': MISSING, 'note': 'that gist belongs to ' + login.lower()}
    if not token_present(gist_text(document), token):
        return {'status': MISSING, 'note': 'the gist does not carry the token'}
    return {'status': VERIFIED, 'note': 'the token is published by that account'}

def _as_dict(key: str, claim: Claim) -> dict:
    return {'claim_id': key, 'owner': claim.owner.as_hex, 'kind': claim.kind, 'resource': claim.resource, 'locator': claim.locator, 'token': claim.token, 'url': claim.url, 'opened_at': claim.opened_at, 'status': claim.status, 'checked_at': claim.checked_at, 'note': claim.note}
